<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Database;Auth::requireAdmin();$pdo=Database::connection();$events=$pdo->query("SELECT DISTINCT e.id,e.name,e.event_date FROM bdc_events e JOIN bdc_scoring_rounds r ON r.event_id=e.id ORDER BY e.event_date DESC,e.name")->fetchAll();$rounds=$pdo->query("SELECT r.id,r.event_id,r.division,r.round_type,r.scoring_mode,r.status FROM bdc_scoring_rounds r ORDER BY r.event_id,r.division,FIELD(r.round_type,'heats','semifinal','final'),r.id")->fetchAll();$controlBase=url('admin/live-screen/control.php');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Live Screen Projector | BDC</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f4f6f9}.workspace{border:0;border-radius:16px}.round-chip{border:1px solid #dee2e6;border-radius:10px;padding:10px 14px;background:#fff;touch-action:manipulation}.round-chip.active{border-color:#dc3545;background:#fff4f5}.control-frame{width:100%;border:0;min-height:720px;background:transparent}.top-actions{display:flex;gap:8px}@media(max-width:767.98px){main.container{max-width:none;padding-left:10px;padding-right:10px}.navbar-brand{font-size:1rem}.top-actions .btn{padding:.35rem .55rem;font-size:.8rem}.workspace .card-body{padding:14px}.round-chip{flex:1 1 auto;min-height:44px}.control-frame{min-height:1100px;border-radius:12px;background:#fff}#mobileHint{display:block!important}}@media(min-width:768px){#mobileHint{display:none!important}}</style></head><body><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="../scoring/">BDC Scoring</a><div class="top-actions"><button type="button" class="btn btn-outline-light btn-sm" onclick="history.back()">← Back</button><a class="btn btn-light btn-sm" href="../">⌂ Dashboard</a></div></div></nav><main class="container py-4"><div class="mb-4"><div class="text-uppercase text-danger fw-bold small">EVENT PRESENTATION</div><h1 class="h2">Live Screen Projector</h1><p class="text-muted">Select Event → Category → Round. Projector controls load directly below.</p></div><div class="card workspace shadow-sm mb-4"><div class="card-body"><div class="row g-3"><div class="col-md-5"><label class="form-label fw-bold">Event</label><select id="event" class="form-select"><option value="">Select event...</option><?php foreach($events as $e):?><option value="<?=(int)$e['id']?>"><?=e($e['name'])?><?=!empty($e['event_date'])?' · '.e($e['event_date']):''?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label fw-bold">Category / Division</label><select id="division" class="form-select" disabled><option value="">Select category...</option></select></div><div class="col-md-3"><label class="form-label fw-bold">Round</label><select id="round" class="form-select" disabled><option value="">Select round...</option></select></div></div></div></div><section id="selected" class="d-none"><div class="mb-3"><div class="small text-muted">AVAILABLE ROUNDS</div><div id="roundsBar" class="d-flex flex-wrap gap-2 mt-2"></div></div><div id="mobileHint" class="d-none alert alert-light border small">Mobile control stays on this authenticated page. Scroll below to use the projector controls.</div><iframe id="controlFrame" class="control-frame" title="Live Screen Control"></iframe></section></main><script>const rounds=<?=json_encode($rounds,JSON_UNESCAPED_SLASHES)?>,controlBase=<?=json_encode($controlBase)?>,eventEl=document.querySelector('#event'),divisionEl=document.querySelector('#division'),roundEl=document.querySelector('#round'),selected=document.querySelector('#selected'),frame=document.querySelector('#controlFrame'),bar=document.querySelector('#roundsBar');const label=s=>String(s).replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());function divisions(){const id=Number(eventEl.value),vals=[...new Set(rounds.filter(r=>Number(r.event_id)===id).map(r=>r.division))];divisionEl.innerHTML='<option value="">Select category...</option>'+vals.map(v=>`<option value="${v}">${label(v)}</option>`).join('');divisionEl.disabled=!id;roundEl.innerHTML='<option value="">Select round...</option>';roundEl.disabled=true;selected.classList.add('d-none');frame.removeAttribute('src')}function roundOptions(){const id=Number(eventEl.value),d=divisionEl.value,vals=rounds.filter(r=>Number(r.event_id)===id&&r.division===d);roundEl.innerHTML='<option value="">Select round...</option>'+vals.map(r=>`<option value="${r.id}">${label(r.round_type)}</option>`).join('');roundEl.disabled=!d;renderBar(vals);selected.classList.add('d-none');frame.removeAttribute('src')}function renderBar(vals){bar.innerHTML=vals.map(r=>`<button type="button" class="round-chip" data-id="${r.id}">${label(r.round_type)}</button>`).join('');bar.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{roundEl.value=b.dataset.id;show()}))}function show(){const r=rounds.find(x=>Number(x.id)===Number(roundEl.value));if(!r){selected.classList.add('d-none');return}bar.querySelectorAll('button').forEach(b=>b.classList.toggle('active',Number(b.dataset.id)===Number(r.id)));const sep=controlBase.includes('?')?'&':'?';frame.src=controlBase+sep+'embed=1&round_id='+encodeURIComponent(r.id)+'&_='+Date.now();selected.classList.remove('d-none');setTimeout(()=>{if(window.innerWidth<768)frame.scrollIntoView({behavior:'smooth',block:'start'})},100)}eventEl.addEventListener('change',divisions);divisionEl.addEventListener('change',roundOptions);roundEl.addEventListener('change',show);window.addEventListener('message',e=>{if(e.data&&e.data.type==='bdc-control-height')frame.style.height=Math.max(window.innerWidth<768?1000:620,Number(e.data.height)||720)+'px'});</script></body></html>